for agent in agents:
    os.makedirs(agent['folder'], exist_ok=True)
    
    # Scrittura configurazione dell'agente
    config_content = f"""# {agent['name']}

**Descrizione:**
{agent['description']}

**Modello suggerito:**
`{agent['model']}`

## System Instructions (da incollare nell'interfaccia)
```text
{agent['system_instruction']}
```"""
    with open(os.path.join(agent['folder'], 'agent_config.md'), 'w', encoding='utf-8') as f:
        f.write(config_content)
        
    # Scrittura estratto normativo
    with open(os.path.join(agent['folder'], 'normativa_estratto.md'), 'w', encoding='utf-8') as f:
        f.write(agent['normativa'])

print("Struttura agenti generata ed allineata con successo.")
